import numpy as np
import os
import pandas as pd
from obspy.signal.trigger import recursive_sta_lta, trigger_onset, aic_simple
from obspy import Trace, Stream

def get_aic_pick(data, initial_idx, window_samples):
    start_aic = max(0, initial_idx - window_samples)
    end_aic = min(len(data), initial_idx + window_samples)
    if end_aic - start_aic < 10:
        return initial_idx
    try:
        aic_vals = aic_simple(data[start_aic:end_aic])
        return np.argmin(aic_vals) + start_aic
    except:
        return initial_idx

def pick_phases(file_path):
    data_npz = np.load(file_path)
    data = data_npz['data']
    dt = data_npz['dt']
    channels_val = data_npz['channels']
    df = 1.0 / dt

    channels_str = str(channels_val.item()) if isinstance(channels_val, np.ndarray) else str(channels_val)
    channels_list = channels_str.split(',')

    z_idx = -1
    h_indices = []

    if len(channels_list) == 3:
        for i, ch in enumerate(channels_list):
            if ch.endswith('Z'): z_idx = i
            elif ch.endswith('E') or ch.endswith('N') or ch.endswith('1') or ch.endswith('2'):
                h_indices.append(i)
    else:
        for i in range(3):
            if np.max(np.abs(data[:, i])) > 0:
                if 'Z' in channels_str: z_idx = i
                else: h_indices.append(i)

    if z_idx == -1 and len(h_indices) == 0:
        energies = np.max(np.abs(data), axis=0)
        z_idx = np.argmax(energies)

    picks = []

    p_idx = None
    if z_idx != -1:
        tr_z = Trace(data=data[:, z_idx], header={'delta': dt})
        tr_z_filt = tr_z.copy().filter('bandpass', freqmin=2.0, freqmax=15.0)
        cft = recursive_sta_lta(tr_z_filt.data, int(0.1*df), int(2.0*df))
        onsets = trigger_onset(cft, 3.5, 1.5)
        if len(onsets) > 0:
            idx = onsets[0][0]
            tr_z_refine = tr_z.copy().filter('bandpass', freqmin=5.0, freqmax=20.0)
            p_idx = get_aic_pick(tr_z_refine.data, idx, int(0.4 * df))
            picks.append(('P', int(p_idx)))
        elif np.max(cft) > 2.0:
            onsets = trigger_onset(cft, 2.0, 1.2)
            if len(onsets) > 0:
                idx = onsets[0][0]
                p_idx = get_aic_pick(tr_z_filt.data, idx, int(0.4 * df))
                picks.append(('P', int(p_idx)))

    s_data = None
    if h_indices:
        h_energy = np.zeros(len(data))
        for idx in h_indices:
            tr_h = Trace(data=data[:, idx], header={'delta': dt})
            tr_h.filter('bandpass', freqmin=1.0, freqmax=10.0)
            h_energy += tr_h.data**2
        s_data = np.sqrt(h_energy)
    elif z_idx != -1:
        tr_z_s = Trace(data=data[:, z_idx], header={'delta': dt})
        tr_z_s.filter('bandpass', freqmin=1.0, freqmax=5.0)
        s_data = np.abs(tr_z_s.data)

    if s_data is not None:
        cft_s = recursive_sta_lta(s_data, int(0.5*df), int(5.0*df))
        search_start = int(p_idx + 0.1 * df) if p_idx is not None else 0
        onsets_s = trigger_onset(cft_s[search_start:], 3.0, 1.5)
        if len(onsets_s) > 0:
            idx_s = onsets_s[0][0] + search_start
            s_idx = get_aic_pick(s_data, idx_s, int(0.8 * df))
            if p_idx is None or s_idx > p_idx + 5:
                picks.append(('S', int(s_idx)))
        elif np.max(cft_s[search_start:]) > 1.5:
             onsets_s = trigger_onset(cft_s[search_start:], 1.5, 1.1)
             if len(onsets_s) > 0:
                idx_s = onsets_s[0][0] + search_start
                s_idx = get_aic_pick(s_data, idx_s, int(0.8 * df))
                if p_idx is None or s_idx > p_idx + 5:
                    picks.append(('S', int(s_idx)))

    return picks

data_dir = '/root/data'
files = sorted([f for f in os.listdir(data_dir) if f.endswith('.npz')])
all_results = []
for f in files:
    try:
        picks = pick_phases(os.path.join(data_dir, f))
        for phase, idx in picks:
            all_results.append({'file_name': f, 'phase': phase, 'pick_idx': idx})
    except: pass
pd.DataFrame(all_results).to_csv('/root/results.csv', index=False)
